fn read24(bytes: []const u8) u21 {
    return @intCast(@as(u32, bytes[0]) | (@as(u32, bytes[1]) << 8) | (@as(u32, bytes[2]) << 16));
}
fn find(data: []const u8, size: usize, key: u21) ?usize {
    var lo: usize = 0;
    var hi = data.len / size;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const got = read24(data[mid * size ..]);
        if (got < key) lo = mid + 1 else hi = mid;
    }
    return if (lo < data.len / size and read24(data[lo * size ..]) == key) lo * size else null;
}
fn ccc(cp: u21) u8 {
    return if (find(classes, 4, cp)) |i| classes[i + 3] else 0;
}
fn compose(first: u21, second: u21) ?u21 {
    if (first >= 0x1100 and first < 0x1113 and second >= 0x1161 and second < 0x1176)
        return 0xac00 + (first - 0x1100) * 588 + (second - 0x1161) * 28;
    if (first >= 0xac00 and first <= 0xd7a3 and (first - 0xac00) % 28 == 0 and second > 0x11a7 and second < 0x11c3)
        return first + second - 0x11a7;
    const key = (@as(u64, first) << 21) | second;
    var lo: usize = 0;
    var hi = compositions.len / 9;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const at = mid * 9;
        const got = (@as(u64, read24(compositions[at..])) << 21) | read24(compositions[at + 3 ..]);
        if (got < key) lo = mid + 1 else hi = mid;
    }
    const at = lo * 9;
    if (at == compositions.len or read24(compositions[at..]) != first or read24(compositions[at + 3 ..]) != second) return null;
    return read24(compositions[at + 6 ..]);
}
pub const max_expanded_bytes = 8 * 1024 * 1024;
pub const max_reorder_steps = 8 * 1024 * 1024;
