fn width(cp: u21) usize {
    return if (cp < 0x80) 1 else if (cp < 0x800) 2 else if (cp < 0x10000) 3 else 4;
}
const Budget = struct {
    points: usize = 0,
    bytes: usize = 0,
    fn point(self: *Budget, cp: u21) !void {
        const size = width(cp);
        self.bytes = try std.math.add(usize, self.bytes, size);
        self.points = try std.math.add(usize, self.points, 1);
    }
};
const PointWriter = struct {
    points: []u21,
    at: usize = 0,
    fn point(self: *PointWriter, cp: u21) !void {
        self.points[self.at] = cp;
        self.at += 1;
    }
};
fn expand(cp: u21, destination: anytype) !void {
    if (cp >= 0xac00 and cp <= 0xd7a3) {
        const s = cp - 0xac00;
        try destination.point(0x1100 + s / 588);
        try destination.point(0x1161 + (s % 588) / 28);
        if (s % 28 != 0) try destination.point(0x11a7 + s % 28);
    } else if (find(decompositions, 7, cp)) |i| {
        const offset: usize = read24(decompositions[i + 3 ..]);
        const len: usize = decompositions[i + 6];
        var d = (try std.unicode.Utf8View.init(decomposition_text[offset..][0..len])).iterator();
        while (d.nextCodepoint()) |part| try destination.point(part);
    } else try destination.point(cp);
}

pub fn nfkc(context: @import("root.zig").Context, text: []const u8) ![]const u8 {
