    }
    var result_len: usize = 0;
    var starter: ?usize = null;
    var last_class: u8 = 0;
    for (points) |cp| {
        try io.checkCancel();
        const cls = ccc(cp);
        if (starter) |s| {
            if (last_class < cls or last_class == 0) {
                if (compose(points[s], cp)) |combined| {
                    points[s] = combined;
                    continue;
                }
            }
        }
        if (cls == 0) starter = result_len;
        last_class = cls;
        points[result_len] = cp;
        result_len += 1;
    }
    const result = points[0..result_len];
    var output_bytes: usize = 0;
    for (result) |cp| {
        try io.checkCancel();
        output_bytes = try std.math.add(usize, output_bytes, width(cp));
    }
    context.warnSize("text.normalize_nfkc", "normalized bytes", output_bytes, max_expanded_bytes);
    const output = try a.alloc(u8, output_bytes);
